package wgmodern;
import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.network.chat.Component;import net.minecraft.client.Minecraft;import net.minecraft.world.item.ItemStack;import mezz.jei.api.*;import mezz.jei.api.recipe.*;import mezz.jei.api.registration.*;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.helpers.IGuiHelper;
/** Reproduces the original two NEI recipe panels; recipe knowledge never limits browsing. */
@JeiPlugin
public class WGJei implements IModPlugin {
 public static final RecipeType<SpinningRecipe> SPIN=RecipeType.create("witchinggadgets","spinning",SpinningRecipe.class);
 public static final RecipeType<BlastRecipe> BLAST=RecipeType.create("witchinggadgets","blast",BlastRecipe.class);
 private static mezz.jei.api.runtime.IJeiRuntime runtime;private static List<SpinningRecipe> spinning=List.of();private static List<BlastRecipe> blast=List.of();
 public ResourceLocation getPluginUid(){return new ResourceLocation("witchinggadgets","main");}
 public void registerCategories(IRecipeCategoryRegistration r){r.addRecipeCategories(new SpinningCategory(r.getJeiHelpers().getGuiHelper()),new BlastCategory(r.getJeiHelpers().getGuiHelper()));}
 public void registerRecipes(IRecipeRegistration r){collect();r.addRecipes(SPIN,spinning);r.addRecipes(BLAST,blast);}
 public void registerRecipeCatalysts(IRecipeCatalystRegistration r){r.addRecipeCatalyst(new ItemStack(Content.SPINNING_ITEM.get()),SPIN);r.addRecipeCatalyst(new ItemStack(net.minecraft.world.level.block.Blocks.NETHER_BRICKS),BLAST);}
 public void onRuntimeAvailable(mezz.jei.api.runtime.IJeiRuntime r){runtime=r;refresh();}
 public void onRuntimeUnavailable(){runtime=null;spinning=List.of();blast=List.of();}
 private static void collect(){var l=Minecraft.getInstance().level;if(l==null){spinning=List.of();blast=List.of();return;}spinning=l.getRecipeManager().getAllRecipesFor(Content.SPINNING.get());var recipes=new TreeMap<ResourceLocation,BlastRecipe>();for(var r:l.getRecipeManager().getAllRecipesFor(Content.BLAST_RECIPES.get()))if(!r.output().isEmpty()&&r.input.getItems().length>0)recipes.put(r.id,r);net.minecraftforge.registries.ForgeRegistries.ITEMS.tags().getTagNames().filter(t->t.location().getNamespace().equals("forge")&&t.location().getPath().startsWith("clusters/")).forEach(tag->{for(var item:net.minecraftforge.registries.ForgeRegistries.ITEMS.tags().getTag(tag)){BlastRecipe.find(l,new ItemStack(item)).ifPresent(r->recipes.put(r.id,r));break;}});blast=List.copyOf(recipes.values());}
 public static void refresh(){if(runtime==null)return;var oldSpin=spinning;var oldBlast=blast;collect();var m=runtime.getRecipeManager();if(!oldSpin.equals(spinning)){m.hideRecipes(SPIN,oldSpin);m.addRecipes(SPIN,spinning);m.unhideRecipes(SPIN,spinning);}if(!oldBlast.equals(blast)){m.hideRecipes(BLAST,oldBlast);m.addRecipes(BLAST,blast);m.unhideRecipes(BLAST,blast);}}
 public static class SpinningCategory implements mezz.jei.api.recipe.category.IRecipeCategory<SpinningRecipe>{private final IDrawable background,icon;public SpinningCategory(IGuiHelper g){background=g.createDrawable(new ResourceLocation("witchinggadgets","textures/gui/nei/spinningwheel.png"),5,11,166,106);icon=g.createDrawableItemStack(new ItemStack(Content.SPINNING_ITEM.get()));}public RecipeType<SpinningRecipe> getRecipeType(){return SPIN;}public Component getTitle(){return Component.translatable("tile.WG_WoodenDevice.spinningWheel.name");}public IDrawable getBackground(){return background;}public IDrawable getIcon(){return icon;}public void setRecipe(mezz.jei.api.gui.builder.IRecipeLayoutBuilder b,SpinningRecipe r,IFocusGroup f){for(int i=0;i<r.getIngredients().size();i++)b.addSlot(RecipeIngredientRole.INPUT,21,9+18*i).addIngredients(r.getIngredients().get(i));b.addSlot(RecipeIngredientRole.OUTPUT,126,46).addItemStack(r.getResultItem(Minecraft.getInstance().level.registryAccess()));}}
 public static class BlastCategory implements mezz.jei.api.recipe.category.IRecipeCategory<BlastRecipe>{private final IDrawable background,icon;public BlastCategory(IGuiHelper g){background=g.createDrawable(new ResourceLocation("witchinggadgets","textures/gui/nei/blastfurnace.png"),5,11,166,106);var image=g.drawableBuilder(new ResourceLocation("witchinggadgets","textures/gui/research/icon_blastfurnace.png"),0,0,32,32).setTextureSize(32,32).build();icon=new IDrawable(){public int getWidth(){return 16;}public int getHeight(){return 16;}public void draw(net.minecraft.client.gui.GuiGraphics graphics,int x,int y){graphics.pose().pushPose();graphics.pose().translate(x,y,0);graphics.pose().scale(.5f,.5f,1);image.draw(graphics);graphics.pose().popPose();}};}public RecipeType<BlastRecipe> getRecipeType(){return BLAST;}public Component getTitle(){return Component.translatable("tile.WG_StoneDevice.blastFurnace.name");}public IDrawable getBackground(){return background;}public IDrawable getIcon(){return icon;}public void setRecipe(mezz.jei.api.gui.builder.IRecipeLayoutBuilder b,BlastRecipe r,IFocusGroup f){b.addSlot(RecipeIngredientRole.INPUT,24,24).addItemStacks(Arrays.stream(r.input.getItems()).map(s->s.copyWithCount(r.count)).toList());b.addSlot(RecipeIngredientRole.OUTPUT,126,14).addItemStack(r.output());if(!r.bonus().isEmpty())b.addSlot(RecipeIngredientRole.OUTPUT,126,39).addItemStack(r.bonus());}}
}
